import unittest

from solucao import juntar
from solucao import juntar_e_somar


class TestJuntarDicionarios(unittest.TestCase):
    def test_junta_as_chaves_novas(self):
        """juntar acrescenta as chaves do segundo dicionario"""
        d = {"a": 1}
        juntar(d, {"b": 2})
        self.assertEqual(d, {"a": 1, "b": 2})

    def test_chave_repetida_fica_com_o_valor_novo(self):
        """juntar troca o valor das chaves repetidas"""
        d = {"a": 1}
        juntar(d, {"a": 9})
        self.assertEqual(d, {"a": 9})

    def test_soma_os_valores_depois_de_juntar(self):
        """juntar_e_somar devolve a soma dos valores depois de juntar"""
        self.assertEqual(juntar_e_somar({"a": 1}, {"b": 2}), 3)

    def test_soma_com_chave_repetida(self):
        """juntar_e_somar soma os valores finais quando uma chave se repete"""
        self.assertEqual(juntar_e_somar({"a": 1}, {"a": 9}), 9)

